/**
 * BottomSheet — gesture-driven bottom sheet with 3 snap points.
 *
 * Snap points (distance from bottom of screen):
 *   0 = collapsed  — 120px tall strip
 *   1 = half       — 300px tall
 *   2 = full        — 600px tall
 *
 * The sheet fills the full width and is positioned absolutely
 * at the bottom of its parent.  The three snap heights are
 * relative to the bottom of the screen (collapsed sits 120px
 * above the bottom; half sits 300px above; full reaches 600px
 * below the top of the screen).
 *
 * Usage:
 *   <BottomSheet
 *     snapPoints={[120, 300, 600]}
 *     initialSnapIndex={0}
 *     onSnapChange={(idx) => ...}
 *   >
 *     {content}
 *   </BottomSheet>
 */

import { useCallback } from 'react';
import { Dimensions, LayoutChangeEvent, StyleSheet, View } from 'react-native';
import { Gesture, GestureDetector } from 'react-native-gesture-handler';
import Animated, {
  runOnJS,
  useAnimatedStyle,
  useSharedValue,
  withSpring,
} from 'react-native-reanimated';

import { useTheme } from '../../theme';

const { height: SCREEN_HEIGHT } = Dimensions.get('window');

export type SnapIndex = 0 | 1 | 2;

interface Props {
  /** Three snap point heights in pixels. */
  snapPoints?: [number, number, number];
  /** Index into snapPoints for initial position (default 0 = collapsed). */
  initialSnapIndex?: SnapIndex;
  /** Called whenever the sheet settles at a new snap point. */
  onSnapChange?: (index: SnapIndex) => void;
  /** Optional extra styles applied to the sheet container. */
  containerStyle?: object;
  children?: React.ReactNode;
}

/** Snap point heights used throughout S02 layout. */
export const DEFAULT_SNAP_POINTS: [number, number, number] = [120, 300, 600];

/**
 * Returns the Y offset (from screen bottom) for a given snap index.
 * At index 0 (collapsed) the sheet sits 120px above the bottom.
 * At index 2 (full) the sheet's top is 600px below the top.
 * The sheet height is always SCREEN_HEIGHT.
 */
function snapToOffset(index: SnapIndex, snapPoints: [number, number, number]): number {
  // sheetY is the top of the sheet measured from the TOP of the screen.
  // The sheet is always SCREEN_HEIGHT tall.
  // At index 0: sheet top is at SCREEN_HEIGHT - 120 (120px above bottom)
  // At index 1: sheet top is at SCREEN_HEIGHT - 300
  // At index 2: sheet top is at SCREEN_HEIGHT - 600
  return SCREEN_HEIGHT - snapPoints[index];
}

export function BottomSheet({
  snapPoints = DEFAULT_SNAP_POINTS,
  initialSnapIndex = 0,
  onSnapChange,
  containerStyle,
  children,
}: Props) {
  const { colors } = useTheme();

  // Track the sheet's top Y position (measured from screen top).
  const sheetY = useSharedValue(snapToOffset(initialSnapIndex, snapPoints));
  const startY = useSharedValue(sheetY.value);
  const currentSnap = useSharedValue<SnapIndex>(initialSnapIndex);

  const notifySnapChange = useCallback(
    (idx: SnapIndex) => {
      onSnapChange?.(idx);
    },
    [onSnapChange],
  );

  const findNearestSnap = useCallback(
    (currentY: number): SnapIndex => {
      // Find the snap point whose Y position is closest to currentY
      let nearest = 0;
      let minDist = Math.abs(snapToOffset(0, snapPoints) - currentY);
      for (let i = 1; i < snapPoints.length; i++) {
        const dist = Math.abs(snapToOffset(i as SnapIndex, snapPoints) - currentY);
        if (dist < minDist) {
          minDist = dist;
          nearest = i;
        }
      }
      return nearest as SnapIndex;
    },
    [snapPoints],
  );

  const panGesture = Gesture.Pan()
    .onStart(() => {
      startY.value = sheetY.value;
    })
    .onUpdate((event) => {
      const newY = startY.value + event.translationY;
      // Clamp so the sheet never goes fully off-screen at the top
      const minY = SCREEN_HEIGHT - snapPoints[2]; // full = top-most
      const maxY = SCREEN_HEIGHT - snapPoints[0]; // collapsed = bottom-most
      sheetY.value = Math.max(minY, Math.min(maxY, newY));
    })
    .onEnd(() => {
      const nearest = findNearestSnap(sheetY.value);
      sheetY.value = withSpring(snapToOffset(nearest, snapPoints), {
        damping: 50,
        stiffness: 300,
      });
      if (nearest !== currentSnap.value) {
        currentSnap.value = nearest;
        runOnJS(notifySnapChange)(nearest);
      }
    });

  const animatedStyle = useAnimatedStyle(() => ({
    top: sheetY.value,
  }));

  return (
    <GestureDetector gesture={panGesture}>
      <Animated.View
        style={[
          styles.sheet,
          { backgroundColor: colors.surface },
          containerStyle,
          animatedStyle,
        ]}
        accessibilityLabel="Bottom sheet"
      >
        <View style={styles.inner}>{children}</View>
      </Animated.View>
    </GestureDetector>
  );
}

const styles = StyleSheet.create({
  sheet: {
    position: 'absolute',
    left: 0,
    right: 0,
    height: SCREEN_HEIGHT,
    borderTopLeftRadius: 20,
    borderTopRightRadius: 20,
    shadowColor: '#000',
    shadowOffset: { width: 0, height: -4 },
    shadowOpacity: 0.15,
    shadowRadius: 12,
    elevation: 10,
    zIndex: 100,
  },
  inner: {
    flex: 1,
  },
});

/**
 * AccessibleToggle — iOS-style animated switch.
 *
 * Uses react-native-reanimated spring animation to drive the knob
 * between off (left) and on (right) positions.
 * Full ARIA roles and state announcements for screen readers.
 *
 * Usage:
 *   <AccessibleToggle
 *     value={settings.accessibleMode}
 *     onValueChange={(v) => setSettings(s => ({ ...s, accessibleMode: v }))}
 *     disabled={false}
 *     accessibilityLabel="Accessible mode"
 *   />
 */

import { Pressable, StyleSheet, View } from 'react-native';
import Animated, {
  useAnimatedStyle,
  useSharedValue,
  withSpring,
} from 'react-native-reanimated';

import { useTheme } from '../../theme';

interface Props {
  /** Current on/off state. */
  value: boolean;
  /** Called when the user toggles the switch. */
  onValueChange: (value: boolean) => void;
  /** Prevent interaction when true. */
  disabled?: boolean;
  /** Screen-reader label for the track. */
  accessibilityLabel?: string;
  /** Screen-reader hint shown when the control is focused. */
  accessibilityHint?: string;
}

// Spring config for a snappy iOS-like feel
const SPRING_CONFIG = {
  damping: 20,
  stiffness: 400,
  mass: 0.6,
};

const TRACK_WIDTH = 51;   // iOS standard
const TRACK_HEIGHT = 31;  // iOS standard
const KNOB_SIZE = 27;     // iOS standard
const KNOB_MARGIN = 2;    // gap between knob and track edge
const KNOB_TRAVEL = TRACK_WIDTH - KNOB_SIZE - KNOB_MARGIN * 2;

export function AccessibleToggle({
  value,
  onValueChange,
  disabled = false,
  accessibilityLabel = 'Toggle switch',
  accessibilityHint = 'Double tap to change setting',
}: Props) {
  const { colors } = useTheme();
  const knobX = useSharedValue(value ? KNOB_TRAVEL : 0);

  const handleToggle = () => {
    const next = !value;
    knobX.value = withSpring(next ? KNOB_TRAVEL : 0, SPRING_CONFIG);
    onValueChange(next);
  };

  const knobStyle = useAnimatedStyle(() => ({
    transform: [{ translateX: knobX.value }],
  }));

  const trackBg = value ? colors.accent : colors.borderMuted;

  return (
    <Pressable
      onPress={disabled ? undefined : handleToggle}
      disabled={disabled}
      accessibilityRole="switch"
      accessibilityState={{ checked: value, disabled }}
      accessibilityLabel={accessibilityLabel}
      accessibilityHint={accessibilityHint}
      style={styles.container}
    >
      <View
        style={[
          styles.track,
          { backgroundColor: trackBg, opacity: disabled ? 0.4 : 1 },
        ]}
      >
        <Animated.View style={[styles.knob, knobStyle]}>
          {/* Knob highlight — subtle inner shine */}
          <View style={styles.knobHighlight} />
        </Animated.View>
      </View>
    </Pressable>
  );
}

const styles = StyleSheet.create({
  container: {
    alignSelf: 'flex-start',
  },
  track: {
    width: TRACK_WIDTH,
    height: TRACK_HEIGHT,
    borderRadius: TRACK_HEIGHT / 2,
    justifyContent: 'center',
    paddingHorizontal: KNOB_MARGIN,
  },
  knob: {
    width: KNOB_SIZE,
    height: KNOB_SIZE,
    borderRadius: KNOB_SIZE / 2,
    backgroundColor: '#ffffff',
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 2 },
    shadowOpacity: 0.2,
    shadowRadius: 3,
    elevation: 4,
    overflow: 'hidden',
  },
  knobHighlight: {
    position: 'absolute',
    top: 2,
    left: 2,
    right: 2,
    height: '40%',
    borderRadius: KNOB_SIZE / 2,
    backgroundColor: 'rgba(255,255,255,0.4)',
  },
});

/**
 * FloatingSearchBar — pill-shaped dual-input search widget.
 *
 * Renders a rounded pill containing:
 *   - Origin TextInput (with a location pin icon)
 *   - Swap button (exchanges origin and destination)
 *   - Destination TextInput (with a target icon)
 *
 * All styling driven by useTheme(). Fully accessible with
 * proper labels, roles, and keyboard navigation.
 *
 * Usage:
 *   <FloatingSearchBar
 *     origin={origin}
 *     destination={destination}
 *     onOriginChange={(text) => ...}
 *     onDestinationChange={(text) => ...}
 *     onSwap={() => setOrigin(destination); setDestination(origin)}
 *     onSearchPress={() => ...}
 *   />
 */

import { useCallback } from 'react';
import {
  Pressable,
  StyleSheet,
  Text,
  TextInput,
  View,
} from 'react-native';
import { useTheme } from '../../theme';

export interface SearchBarInputs {
  origin: string;
  destination: string;
}

export interface FloatingSearchBarProps {
  /** Current origin text. */
  origin: string;
  /** Current destination text. */
  destination: string;
  /** Called when the origin text changes. */
  onOriginChange: (text: string) => void;
  /** Called when the destination text changes. */
  onDestinationChange: (text: string) => void;
  /** Called when the user presses the swap button. */
  onSwap: () => void;
  /** Called when the search/directions button is pressed. */
  onSearchPress: () => void;
  /** Prevent all interactions when true. */
  disabled?: boolean;
  /** Optional extra styles applied to the pill container. */
  style?: object;
}

// ─── Helpers ─────────────────────────────────────────────────────────────────

/** Returns a shorter secondary label for a location field. */
function fieldLabel(placeholder: string): string {
  if (placeholder.toLowerCase().includes('origin')) return 'From';
  if (placeholder.toLowerCase().includes('destination')) return 'To';
  return placeholder;
}

// ─── Component ────────────────────────────────────────────────────────────────

export function FloatingSearchBar({
  origin,
  destination,
  onOriginChange,
  onDestinationChange,
  onSwap,
  onSearchPress,
  disabled = false,
  style,
}: FloatingSearchBarProps) {
  const { colors, spacing, typography } = useTheme();

  const handleSwap = useCallback(() => {
    if (disabled) return;
    onSwap();
  }, [disabled, onSwap]);

  const handleSearch = useCallback(() => {
    if (disabled) return;
    onSearchPress();
  }, [disabled, onSearchPress]);

  const inputStyle = {
    flex: 1,
    height: 40,
    borderRadius: 20,
    paddingHorizontal: spacing.md,
    fontSize: typography.body.fontSize,
    color: colors.textPrimary,
    backgroundColor: colors.surfaceElevated,
  };

  const activeInputStyle = {
    ...inputStyle,
    borderWidth: 1.5,
    borderColor: colors.borderAccent,
  };

  return (
    <View
      style={[
        styles.pill,
        { backgroundColor: colors.surface },
        disabled && styles.pillDisabled,
        style,
      ]}
      accessibilityRole="none"
    >
      {/* Origin field */}
      <View style={styles.fieldWrapper}>
        <Text
          style={[
            styles.fieldIcon,
            { color: colors.textMuted, fontSize: 14 },
          ]}
          accessibilityElementsHidden
        >
          ◎
        </Text>
        <TextInput
          style={[inputStyle, styles.fieldInput]}
          value={origin}
          onChangeText={onOriginChange}
          placeholder="My location"
          placeholderTextColor={colors.textDisabled}
          returnKeyType="next"
          editable={!disabled}
          accessibilityLabel="Origin location"
          accessibilityHint="Enter your starting location"
          testID="search-origin-input"
        />
      </View>

      {/* Swap button */}
      <Pressable
        onPress={handleSwap}
        disabled={disabled}
        accessibilityRole="button"
        accessibilityLabel="Swap origin and destination"
        accessibilityHint="Exchanges the start and end locations"
        style={({ pressed }: { pressed: boolean }) => [
          styles.swapButton,
          { backgroundColor: colors.surfaceElevated },
          pressed && { backgroundColor: colors.borderMuted },
        ]}
        testID="search-swap-btn"
      >
        <Text style={[styles.swapIcon, { color: colors.accent }]}>⇅</Text>
      </Pressable>

      {/* Destination field */}
      <View style={styles.fieldWrapper}>
        <Text
          style={[
            styles.fieldIcon,
            { color: colors.textMuted, fontSize: 14 },
          ]}
          accessibilityElementsHidden
        >
          ⊕
        </Text>
        <TextInput
          style={[inputStyle, styles.fieldInput]}
          value={destination}
          onChangeText={onDestinationChange}
          placeholder="Where to?"
          placeholderTextColor={colors.textDisabled}
          returnKeyType="go"
          onSubmitEditing={handleSearch}
          editable={!disabled}
          accessibilityLabel="Destination"
          accessibilityHint="Enter your destination"
          testID="search-destination-input"
        />
      </View>

      {/* Search button */}
      <Pressable
        onPress={handleSearch}
        disabled={disabled}
        accessibilityRole="button"
        accessibilityLabel="Get directions"
        accessibilityHint="Starts navigation to the destination"
        style={({ pressed }: { pressed: boolean }) => [
          styles.searchButton,
          { backgroundColor: colors.accent },
          pressed && { backgroundColor: colors.accentMuted },
          disabled && styles.buttonDisabled,
        ]}
        testID="search-submit-btn"
      >
        <Text style={[styles.searchIcon, { color: colors.textInverse }]}>→</Text>
      </Pressable>
    </View>
  );
}

// ─── Styles ─────────────────────────────────────────────────────────────────

const styles = StyleSheet.create({
  pill: {
    flexDirection: 'row',
    alignItems: 'center',
    borderRadius: 28,
    paddingHorizontal: 12,
    paddingVertical: 8,
    gap: 6,
    // Shadow
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 2 },
    shadowOpacity: 0.15,
    shadowRadius: 8,
    elevation: 6,
  },
  pillDisabled: {
    opacity: 0.5,
  },
  fieldWrapper: {
    flex: 1,
    flexDirection: 'row',
    alignItems: 'center',
    gap: 4,
  },
  fieldIcon: {
    width: 16,
    textAlign: 'center',
  },
  fieldInput: {
    paddingLeft: 0,
    paddingRight: 8,
  },
  swapButton: {
    width: 32,
    height: 32,
    borderRadius: 16,
    alignItems: 'center',
    justifyContent: 'center',
    flexShrink: 0,
  },
  swapIcon: {
    fontSize: 16,
    fontWeight: '700',
  },
  searchButton: {
    width: 36,
    height: 36,
    borderRadius: 18,
    alignItems: 'center',
    justifyContent: 'center',
    flexShrink: 0,
  },
  buttonDisabled: {
    opacity: 0.5,
  },
  searchIcon: {
    fontSize: 16,
    fontWeight: '700',
  },
});

/**
 * FloatingFloorSwitcher — horizontal scrollable row of floor pills.
 *
 * Renders a horizontally scrolling list of floor-number buttons.
 * The currently selected floor is highlighted with the accent color.
 * Used in the floating UI layer above the map to switch floors quickly.
 *
 * Usage:
 *   <FloatingFloorSwitcher
 *     floors={[{ buildingId: 1, floorNumber: 1 }, { buildingId: 1, floorNumber: 2 }]}
 *     selectedFloor={{ buildingId: 1, floorNumber: 2 }}
 *     onSelectFloor={(target) => setSelectedFloor(target)}
 *   />
 */

import { Pressable, ScrollView, StyleSheet, Text, View } from 'react-native';
import { useTheme } from '../../theme';
import { FloorPlanTarget } from '../../data/mapApiClient';

export interface FloatingFloorSwitcherProps {
  /** All available floors to display as pills. */
  floors: FloorPlanTarget[];
  /** Currently selected floor. */
  selectedFloor: FloorPlanTarget;
  /** Called when the user selects a different floor. */
  onSelectFloor: (target: FloorPlanTarget) => void;
  /** Optional extra styles applied to the scroll container. */
  style?: object;
}

// ─── Helpers ─────────────────────────────────────────────────────────────────

/** Returns a human-readable label for a floor, e.g. "Floor 2". */
function floorLabel(target: FloorPlanTarget): string {
  return `Floor ${target.floorNumber}`;
}

// ─── Component ────────────────────────────────────────────────────────────────

export function FloatingFloorSwitcher({
  floors,
  selectedFloor,
  onSelectFloor,
  style,
}: FloatingFloorSwitcherProps) {
  const { colors, spacing } = useTheme();

  if (!floors || floors.length === 0) {
    return null;
  }

  const isSelected = (target: FloorPlanTarget) =>
    target.buildingId === selectedFloor.buildingId &&
    target.floorNumber === selectedFloor.floorNumber;

  return (
    <View
      style={[
        styles.container,
        { backgroundColor: colors.surface },
        style,
      ]}
      accessibilityLabel="Floor switcher"
      accessibilityRole="tablist"
    >
      <ScrollView
        horizontal
        showsHorizontalScrollIndicator={false}
        contentContainerStyle={styles.scrollContent}
      >
        {floors.map((floor, index) => {
          const selected = isSelected(floor);
          return (
            <Pressable
              key={`${floor.buildingId}-${floor.floorNumber}-${index}`}
              onPress={() => onSelectFloor(floor)}
              accessibilityRole="tab"
              accessibilityState={{ selected }}
              accessibilityLabel={floorLabel(floor)}
              accessibilityHint="Switches to this floor on the map"
              style={({ pressed }: { pressed: boolean }) => [
                styles.pill,
                {
                  backgroundColor: selected
                    ? colors.chipActive
                    : colors.surfaceElevated,
                  borderColor: selected
                    ? colors.borderAccent
                    : colors.borderMuted,
                },
                pressed && {
                  backgroundColor: selected
                    ? colors.accentSubtle
                    : colors.border,
                },
              ]}
              testID={`floor-pill-${floor.floorNumber}`}
            >
              <Text
                style={[
                  styles.pillText,
                  {
                    color: selected
                      ? colors.chipTextActive
                      : colors.textSecondary,
                    fontWeight: selected ? '700' : '500',
                  },
                ]}
              >
                {floor.floorNumber}
              </Text>
            </Pressable>
          );
        })}
      </ScrollView>
    </View>
  );
}

// ─── Styles ─────────────────────────────────────────────────────────────────

const styles = StyleSheet.create({
  container: {
    borderRadius: 22,
    paddingVertical: 6,
    paddingHorizontal: 10,
    // Shadow
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 1 },
    shadowOpacity: 0.12,
    shadowRadius: 4,
    elevation: 4,
  },
  scrollContent: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 6,
  },
  pill: {
    minWidth: 36,
    height: 32,
    borderRadius: 16,
    borderWidth: 1,
    alignItems: 'center',
    justifyContent: 'center',
    paddingHorizontal: 12,
  },
  pillText: {
    fontSize: 14,
  },
});

/**
 * DirectionStepCard — single turn-by-turn instruction card.
 *
 * Displays a direction step with icon, instruction text, distance, and
 * duration.  State-based accent coloring:
 *   - default    → normal surface styling
 *   - active     → accent border highlight
 *   - accessible → success accent (for elevator/ramp segments)
 *   - stairs     → warning accent (for stairs steps)
 *   - arrived    → green highlight for the final destination step
 *
 * DirectionStep typed from mobile/domain/navGraph.ts.
 *
 * Usage:
 *   <DirectionStepCard
 *     step={step}
 *     isActive={index === currentStepIndex}
 *     onPress={() => onStepPress(index)}
 *   />
 */

import { Pressable, StyleSheet, Text, View } from 'react-native';
import { useTheme } from '../../theme';
import { DirectionStep, StepIcon } from '../../domain/navGraph';

export interface DirectionStepCardProps {
  /** The direction step to display. */
  step: DirectionStep;
  /** Highlight the card when this step is the active guidance step. */
  isActive?: boolean;
  /** Called when the user taps the card. */
  onPress?: () => void;
  /** Optional extra styles applied to the card container. */
  style?: object;
}

// ─── Icon helpers ─────────────────────────────────────────────────────────────

const STEP_ICONS: Record<string, string> = {
  'straight': '↑',
  'turn-left': '←',
  'turn-right': '→',
  'sharp-left': '↙',
  'sharp-right': '↘',
  'arrive': '🏁',
  'accessible': '♿',
  'stairs-up': '⬆',
  'stairs-down': '⬇',
  'elevator': '🛗',
  'ramp': '♿',
};

function stepIconEmoji(icon: StepIcon): string {
  return STEP_ICONS[icon] ?? '→';
}

// ─── Distance / duration formatting ────────────────────────────────────────────

/**
 * Format normalized distance as a human-readable string.
 * 1 normalized unit ≈ 50 m.
 */
function formatDistance(norm: number): string {
  const meters = Math.round(norm * 50);
  if (meters < 1) return '<1m';
  if (meters >= 1000) return `${(meters / 1000).toFixed(1)}km`;
  return `${meters}m`;
}

/** Format seconds as a human-readable duration string. */
function formatDuration(seconds: number): string {
  if (seconds < 60) return `${seconds}s`;
  const mins = Math.floor(seconds / 60);
  const secs = seconds % 60;
  if (secs === 0) return `${mins}min`;
  return `${mins}min ${secs}s`;
}

// ─── Accent variant ───────────────────────────────────────────────────────────

type AccentVariant = 'default' | 'active' | 'accessible' | 'stairs' | 'arrived';

function accentVariant(step: DirectionStep, isActive?: boolean): AccentVariant {
  if (step.icon === 'arrive') return 'arrived';
  if (isActive) return 'active';
  if (step.icon === 'elevator' || step.icon === 'ramp') return 'accessible';
  if (step.icon === 'stairs-up' || step.icon === 'stairs-down') return 'stairs';
  return 'default';
}

// ─── Component ────────────────────────────────────────────────────────────────

export function DirectionStepCard({
  step,
  isActive = false,
  onPress,
  style,
}: DirectionStepCardProps) {
  const { colors } = useTheme();

  const variant = accentVariant(step, isActive);

  const borderColor =
    variant === 'arrived'
      ? colors.success
      : variant === 'active'
        ? colors.borderAccent
        : variant === 'accessible'
          ? colors.success
          : variant === 'stairs'
            ? colors.warning
            : colors.guidanceCardBorder;

  const iconBgColor =
    variant === 'arrived'
      ? colors.successSubtle
      : variant === 'accessible'
        ? colors.successSubtle
        : variant === 'stairs'
          ? colors.warning + '33'  // warning with alpha
          : colors.guidanceStepIcon;

  const iconColor =
    variant === 'arrived'
      ? colors.success
      : variant === 'accessible'
        ? colors.success
        : variant === 'stairs'
          ? colors.warning
          : colors.accent;

  const cardBg =
    variant === 'arrived'
      ? colors.successSubtle
      : colors.guidanceCard;

  const textColor =
    variant === 'arrived'
      ? colors.successMuted
      : variant === 'active'
        ? colors.textPrimary
        : colors.textSecondary;

  const distanceColor =
    variant === 'arrived'
      ? colors.success
      : variant === 'accessible'
        ? colors.successMuted
        : variant === 'stairs'
          ? colors.warningMuted
          : colors.accent;

  const icon = stepIconEmoji(step.icon);
  const distance = formatDistance(step.distanceM);
  const duration = formatDuration(step.durationSec);

  const CardWrapper = onPress ? Pressable : View;

  return (
    <CardWrapper
      onPress={onPress}
      accessibilityRole="button"
      accessibilityLabel={`${step.instruction}, ${distance}, ${duration}`}
      accessibilityHint="Tap to highlight this step on the map"
      style={({ pressed }: { pressed: boolean }) => [
        styles.card,
        {
          backgroundColor: cardBg,
          borderColor,
          borderWidth: variant === 'default' ? 1 : 1.5,
        },
        pressed && onPress && styles.cardPressed,
        style,
      ]}
      testID={`direction-step-card-${step.icon}`}
    >
      {/* Icon container */}
      <View
        style={[
          styles.iconContainer,
          { backgroundColor: iconBgColor },
        ]}
      >
